set -o pipefail; cd webviews
export CMUX_BROWSER_TESTS=1
T="test/transcript-insert-restyle.test.ts test/transcript-has-marks.test.ts src/agent-session/acpmux/conversation/PendingSteer.test.tsx"
echo "=== HEAD"; bun test $T 2>&1 | tee "$FAST_CHECKS_OUT/head.txt" || exit 1
echo '' | base64 -d | gunzip > /tmp/fix.patch
cd .. && git apply -R /tmp/fix.patch && cd webviews || exit 1
echo "=== BASE (fix reverted): each must fail"
fails=0; for f in $T; do if bun test $f > "$FAST_CHECKS_OUT/base-$(basename $f).txt" 2>&1; then echo "BASE PASSED $f"; exit 1; else fails=$((fails+1)); echo "base fails $f"; grep -E "TRANSCRIPT-INSERT|Expected|Received|\(fail\)" "$FAST_CHECKS_OUT/base-$(basename $f).txt" | head -8; fi; done
echo "=== base failures: $fails of 3"; [ "$fails" = 3 ]
